// Parity of the "core" area with Python: RNG, character table, pk3, species and validation.
// Vectors generated by tools/parity/core.py (uv run python tools/gen_parity_vectors.py core). The RNG part
// lives in vectors/frozen/rng.json, frozen because the RNG only exists in TS now: do not regenerate.
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, test } from "vitest";
import { setLang } from "../src/i18n";
import * as charset from "../src/lib/gen3/charset";
import * as pk3 from "../src/lib/gen3/pk3";
import { Pk3, type Stat, type StatValues } from "../src/lib/gen3/pk3";
import * as rng from "../src/lib/gen3/rng";
import * as species from "../src/lib/gen3/species";
import * as validate from "../src/lib/gen3/validate";

type Json = Record<string, unknown>;
interface SpreadVector { seed: number; pid: number; ivs: StatValues; calls: number; nature: number; tid: number; sid: number; shiny: boolean; want?: number }
interface MonVector { plain: string; raw: string; checksum: number; fields: Json; box: string }
interface EditVector { before: string; sets: Json; after: string; party?: { level: number; stats: StatValues; current_hp: number | null } }
interface IssueCase { name: string; data: string; pt: [string, string, string][]; en: [string, string, string][]; valid: boolean }

interface Vectors {
  rng: {
    mult_inv: number; add_inv: number;
    steps: [number, number, number][];
    advance: [number, number, number][];
    distance: [number, number, number][];
    sequences: { seed: number; values: number[]; state: number; calls: number }[];
    static: SpreadVector[];
    wild: SpreadVector[];
    search: { initial: number; first: number; last: number; min: Partial<Record<Stat, number>>; found: [number, number, number][] }[];
  };
  charset: { decode: [string, boolean, string][]; encode: [string, number, string][]; encode_errors: [string, number][] };
  pk3: { mons: MonVector[]; load: { data: string; plain: string; encrypted: boolean }[]; edits: EditVector[] };
  species: {
    ids: number[];
    calc_stats: { species: number; level: number; ivs: StatValues; evs: StatValues; nature: number; stats: StatValues }[];
    level_from_exp: [number, number, number][];
    gender: [number, number, species.Gender][];
    hidden_power: [StatValues, [number, number]][];
    trade_evolution: [number, number, number | null][];
    learnable: { species: number; level: number; own: number[]; all: number[]; all_max: number[] }[];
    possible_ivs: { species: number; nature: number; observations: species.Observation[]; evs: StatValues | null; ev_slack?: number; ivs: Record<Stat, number[]> }[];
    names: Record<"moves" | "types" | "abilities" | "items" | "mapsec", [number, string][]> & { national: [number, number][]; species_id: [string, number][] };
    nature_modifier: [number, Stat, number][];
    evolutions: [number, species.Evolution[], number[]][];
    egg_father: [number, number[], number | null][];
    since: [number, number, number[], number[]][];
  };
  validate: { cases: IssueCase[]; valid_species: number[] };
}

const V = {
  ...JSON.parse(readFileSync(join(__dirname, "vectors", "core.json"), "utf8")),
  rng: JSON.parse(readFileSync(join(__dirname, "vectors", "frozen", "rng.json"), "utf8")),
} as Vectors;

const bytes = (hex: string) => Uint8Array.from(hex.match(/../g) ?? [], (b) => parseInt(b, 16));
const hex = (data: Uint8Array) => Array.from(data, (b) => b.toString(16).padStart(2, "0")).join("");
const sorted = (set: Set<number>) => [...set].sort((a, b) => a - b);

describe("rng", () => {
  test("constants", () => {
    expect([rng.MULT_INV, rng.ADD_INV]).toEqual([V.rng.mult_inv, V.rng.add_inv]);
  });

  test("nextSeed and prevSeed", () => {
    for (const [seed, next, prev] of V.rng.steps) expect([rng.nextSeed(seed), rng.prevSeed(seed)], `${seed}`).toEqual([next, prev]);
  });

  test("advance with large and negative n", () => {
    for (const [seed, n, out] of V.rng.advance) expect(rng.advance(seed, n), `${seed} ${n}`).toBe(out);
  });

  test("distance", () => {
    for (const [origin, target, n] of V.rng.distance) expect(rng.distance(origin, target), `${origin} ${target}`).toBe(n);
  });

  test("Rng.random and random32", () => {
    for (const s of V.rng.sequences) {
      const g = new rng.Rng(s.seed);
      const values = [...Array.from({ length: 6 }, () => g.random()), ...Array.from({ length: 4 }, () => g.random32())];
      expect({ values, state: g.state, calls: g.calls }).toEqual({ values: s.values, state: s.state, calls: s.calls });
    }
  });

  const spread = (sp: rng.Spread, v: SpreadVector) => ({
    seed: sp.seed, pid: sp.pid, ivs: sp.ivs, calls: sp.calls, nature: sp.nature, tid: v.tid, sid: v.sid, shiny: sp.isShiny(v.tid, v.sid),
  });

  test("staticSpread", () => {
    for (const v of V.rng.static) expect(spread(rng.staticSpread(v.seed), v)).toEqual(v);
  });

  test("wildSpreadFromNature", () => {
    for (const { want, ...v } of V.rng.wild) expect(spread(rng.wildSpreadFromNature(v.seed, want!), v)).toEqual(v);
  });

  test("searchStatic with minIvs", () => {
    for (const s of V.rng.search) {
      const found = rng.searchStatic(s.initial, s.first, s.last, rng.minIvs(s.min)).map(([n, sp]) => [n, sp.pid, sp.seed]);
      expect(found).toEqual(s.found);
    }
    expect(() => rng.minIvs({ luck: 3 } as never)).toThrow();
  });
});

describe("charset", () => {
  test("Western and Japanese decode", () => {
    for (const [data, jp, text] of V.charset.decode) expect(charset.decode(bytes(data), jp), data).toBe(text);
  });

  test("encode", () => {
    for (const [text, length, data] of V.charset.encode) expect(hex(charset.encode(text, length)), text).toBe(data);
    for (const [text, length] of V.charset.encode_errors) expect(() => charset.encode(text, length), text).toThrow();
  });
});

// Vector field (Python name) to the TS getter.
const PK3_FIELDS: Record<string, (m: Pk3) => unknown> = {
  personality: (m) => m.personality, ot_id: (m) => m.otId, tid: (m) => m.tid, sid: (m) => m.sid,
  language: (m) => m.language, is_bad_egg: (m) => m.isBadEgg, has_species: (m) => m.hasSpecies,
  markings: (m) => m.markings, nickname: (m) => m.nickname, ot_name: (m) => m.otName, species: (m) => m.species,
  held_item: (m) => m.heldItem, experience: (m) => m.experience, pp_bonuses: (m) => m.ppBonuses,
  friendship: (m) => m.friendship, moves: (m) => m.moves, pp: (m) => m.pp, evs: (m) => m.evs, contest: (m) => m.contest,
  pokerus: (m) => m.pokerus, met_location: (m) => m.metLocation, met_level: (m) => m.metLevel, met_game: (m) => m.metGame,
  ball: (m) => m.ball, ot_gender: (m) => m.otGender, is_egg: (m) => m.isEgg, ability_num: (m) => m.abilityNum,
  fateful: (m) => m.fateful, ribbons: (m) => m.ribbons, ivs: (m) => m.ivs, nature: (m) => m.nature,
  is_shiny: (m) => m.isShiny, checksum_ok: (m) => m.checksumOk, is_party: (m) => m.isParty,
  level: (m) => m.level, stats: (m) => m.stats,
};

const readPk3 = (mon: Pk3) => Object.fromEntries(Object.keys(PK3_FIELDS).filter((k) => mon.isParty || (k !== "level" && k !== "stats")).map((k) => [k, PK3_FIELDS[k](mon)]));

// TS setter name for each writable Python field.
const PK3_SETTERS: Record<string, keyof Pk3> = {
  personality: "personality", ot_id: "otId", language: "language", has_species: "hasSpecies", markings: "markings",
  species: "species", held_item: "heldItem", experience: "experience", pp_bonuses: "ppBonuses", friendship: "friendship",
  moves: "moves", pp: "pp", evs: "evs", pokerus: "pokerus", met_location: "metLocation", met_level: "metLevel",
  met_game: "metGame", ball: "ball", ot_gender: "otGender", ability_num: "abilityNum", ivs: "ivs",
  nickname: "nickname", ot_name: "otName",
};

describe("pk3", () => {
  test("encryption, checksum and fields", () => {
    for (const v of V.pk3.mons) {
      const plain = bytes(v.plain);
      expect(pk3.checksum(plain)).toBe(v.checksum);
      const mon = new Pk3(plain);
      expect(hex(mon.toRaw())).toBe(v.raw);
      expect(hex(pk3.encrypt(plain))).toBe(v.raw);
      expect(hex(Pk3.fromRaw(bytes(v.raw)).data), v.plain).toBe(hex(pk3.decrypt(bytes(v.raw))));
      expect(readPk3(mon), v.plain).toEqual(v.fields);
      expect(hex(mon.toBox().data)).toBe(v.box);
      if (v.fields.checksum_ok) expect(hex(Pk3.fromRaw(bytes(v.raw)).data)).toBe(v.plain);
      if (!mon.isParty) expect(() => mon.level).toThrow();
    }
  });

  test("load detects the format by the checksum", () => {
    for (const v of V.pk3.load) {
      const [mon, encrypted] = pk3.load(bytes(v.data));
      expect([hex(mon.data), encrypted]).toEqual([v.plain, v.encrypted]);
    }
  });

  test("setters and setParty", () => {
    for (const v of V.pk3.edits) {
      const mon = new Pk3(bytes(v.before));
      const target = mon as unknown as Record<string, unknown>;
      for (const [key, value] of Object.entries(v.sets)) target[PK3_SETTERS[key]] = value;
      if (v.party) mon.setParty(v.party.level, v.party.stats, v.party.current_hp);
      mon.updateChecksum();
      expect(hex(mon.data)).toBe(v.after);
    }
  });

  test("input errors", () => {
    expect(() => new Pk3(new Uint8Array(81))).toThrow();
    const mon = new Pk3(new Uint8Array(pk3.BOX_SIZE));
    expect(() => { mon.ivs = { hp: 32, attack: 0, defense: 0, speed: 0, sp_attack: 0, sp_defense: 0 }; }).toThrow();
  });
});

describe("species", () => {
  test("calcStats, with the nature's 16-bit overflow", () => {
    for (const v of V.species.calc_stats) expect(species.calcStats(v.species, v.level, v.ivs, v.evs, v.nature)).toEqual(v.stats);
  });

  test("levelFromExp", () => {
    for (const [s, exp, level] of V.species.level_from_exp) expect(species.levelFromExp(s, exp), `${s} ${exp}`).toBe(level);
  });

  test("gender and hiddenPower", () => {
    for (const [s, pid, g] of V.species.gender) expect(species.gender(s, pid)).toBe(g);
    for (const [ivs, out] of V.species.hidden_power) expect(species.hiddenPower(ivs)).toEqual(out);
  });

  test("breeding chain (eggFather) and catch form (since)", () => {
    for (const [s, moves, father] of V.species.egg_father) expect(species.eggFather(s, moves), `${s} ${moves}`).toBe(father);
    for (const [s, form, learn, xd] of V.species.since) {
      expect(sorted(species.learnableMoves(s, 50, false, form)), `${s} from ${form}`).toEqual(learn);
      expect(sorted(species.xdTutorMoves(s, form)), `${s} from ${form}`).toEqual(xd);
    }
  });

  test("tradeEvolution, evolutions and preEvolutions", () => {
    for (const [s, item, out] of V.species.trade_evolution) expect(species.tradeEvolution(s, item), `${s} ${item}`).toBe(out);
    for (const [s, evos, pre] of V.species.evolutions) expect([species.evolutions(s), species.preEvolutions(s)]).toEqual([evos, pre]);
  });

  test("learnable moves", () => {
    for (const v of V.species.learnable) {
      expect(sorted(species.ownLearnableMoves(v.species, v.level))).toEqual(v.own);
      expect(sorted(species.learnableMoves(v.species, v.level))).toEqual(v.all);
      expect(sorted(species.learnableMoves(v.species))).toEqual(v.all_max);
    }
  });

  test("possibleIvs", () => {
    for (const v of V.species.possible_ivs) expect(species.possibleIvs(v.species, v.nature, v.observations, v.evs, v.ev_slack ?? 0)).toEqual(v.ivs);
  });

  test("names and numbers", () => {
    const n = V.species.names;
    for (const [id, name] of n.moves) expect(species.moveName(id)).toBe(name);
    for (const [id, name] of n.types) expect(species.typeName(id)).toBe(name);
    for (const [id, name] of n.abilities) expect(species.abilityName(id)).toBe(name);
    for (const [id, name] of n.items) expect(species.itemName(id)).toBe(name);
    for (const [id, name] of n.mapsec) expect(species.mapSection(id)).toBe(name);
    for (const [id, national] of n.national) expect(species.nationalNumber(id)).toBe(national);
    for (const [name, id] of n.species_id) expect(species.speciesId(name)).toBe(id);
    expect(Object.keys(species.data().species).map(Number)).toEqual(V.species.ids);
    expect(() => species.info(0)).toThrow();
  });

  test("natureModifier", () => {
    for (const [nature, stat, out] of V.species.nature_modifier) expect(species.natureModifier(nature, stat)).toBe(out);
  });
});

describe("validate", () => {
  const issues = (mon: Pk3) => validate.check(mon).map((i) => [i.level, i.field, i.message]);

  test("validSpecies", () => {
    const valid = Array.from({ length: 0x10000 }, (_, s) => s).filter(validate.validSpecies);
    expect(valid).toEqual(V.validate.valid_species);
  });

  test("check in Portuguese and English", () => {
    for (const c of V.validate.cases) {
      const mon = new Pk3(bytes(c.data));
      expect(issues(mon), c.name).toEqual(c.pt);
      expect(validate.isValid(mon), c.name).toBe(c.valid);
      setLang("en");
      try {
        expect(issues(mon), c.name).toEqual(c.en);
      } finally {
        setLang("pt");
      }
    }
  });
});
